import { api, escapeHtml as h, selectedAccount, toast, wireAccountPicker } from "/static/common.js?v=20260810.1";

const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const state = { csrf:"", payload:null, draft:null, section:"start", dirty:false, activityIndex:0, accounts:[] };
const host = $("#configHost");

function mutation(method, body){ return {method, body, headers:{"X-CSRF-Token":state.csrf}}; }
function darken(hex,amount=34){const clean=String(hex||"#4f46e5").replace("#","");if(!/^[0-9a-f]{6}$/i.test(clean))return"#3730a3";const parts=[0,2,4].map(index=>Math.max(0,parseInt(clean.slice(index,index+2),16)-amount));return`#${parts.map(value=>value.toString(16).padStart(2,"0")).join("")}`;}
function keyOf(value){ return String(value||"").toLowerCase().trim().replace(/[^a-z0-9]+/g,"_").replace(/^_+|_+$/g,"").slice(0,40) || "item"; }
function clone(value){ return JSON.parse(JSON.stringify(value)); }
function pathParts(path){ return path.split(".").map(item => /^\d+$/.test(item) ? Number(item) : item); }
function setPath(path, value){ const parts=pathParts(path); let target=state.draft; parts.slice(0,-1).forEach(part=>target=target[part]); target[parts.at(-1)]=value; markDirty(); }
function getPath(path){ return pathParts(path).reduce((value,key)=>value?.[key],state.draft); }
function markDirty(){ state.dirty=true; $(".config-save-state").className="config-save-state dirty"; $("#configStateText").textContent="Unsaved draft"; }
function markSaved(){ state.dirty=false; $(".config-save-state").className="config-save-state"; $("#configStateText").textContent="Draft saved"; }
function heading(kicker,title,description,actions=""){ return `<div class="config-heading"><div><p class="eyebrow">${h(kicker)}</p><h1>${h(title)}</h1><p class="muted">${h(description)}</p></div><div class="inline-actions">${actions}</div></div>`; }
function option(value,label,current){ return `<option value="${h(value)}" ${String(current)===String(value)?"selected":""}>${h(label)}</option>`; }
function ordinal(value){
  const words=["First","Second","Third","Fourth","Fifth","Sixth","Seventh","Eighth","Ninth","Tenth"];
  const number=Number(value)+1,mod100=number%100;
  if(words[number-1])return`${words[number-1]} choice`;
  if(mod100>=11&&mod100<=13)return`${number}th choice`;
  return`${number}${number%10===1?"st":number%10===2?"nd":number%10===3?"rd":"th"} choice`;
}
function priorityOptions(current,count){
  return Array.from({length:Math.max(count,1)},(_,index)=>option(index,ordinal(index),current)).join("");
}
function uniqueKey(prefix,items,keyName="key"){
  const used=new Set(items.map(item=>String(item[keyName]||"").toLowerCase()));
  let number=items.length+1,candidate=`${prefix}_${number}`;
  while(used.has(candidate)){number+=1;candidate=`${prefix}_${number}`;}
  return candidate;
}
function normalizeCategoryPriorities(settings){
  for(const field of ["primaryPriority","secondaryPriority"]){
    [...settings.categories].sort((a,b)=>Number(a[field])-Number(b[field])||a.name.localeCompare(b.name)).forEach((item,index)=>{item[field]=index;});
  }
}
function percentValue(value){
  const number=Number(value||0)*100;
  return Number.isFinite(number)?number.toFixed(4).replace(/0+$/,'').replace(/\.$/,''):"0";
}
function balanceWeights(items){
  if(!items.length)return;
  const units=10000,base=Math.floor(units/items.length),remainder=units-base*items.length;
  items.forEach((item,index)=>{item.weight=String((base+(index<remainder?1:0))/units);});
}
function durationParts(value){
  const total=Math.max(0,Math.round(Number(value)||0));
  return {hours:Math.floor(total/3600),minutes:Math.floor(total%3600/60),seconds:total%60};
}
function durationTarget(criterionIndex,value){
  const parts=durationParts(value);
  return `<fieldset class="duration-target" data-duration-target="${criterionIndex}"><legend>Full-score target</legend><div><label><span>HH</span><input type="number" min="0" max="99" step="1" inputmode="numeric" data-duration-part="hours" value="${parts.hours}" aria-label="Target hours"></label><span>:</span><label><span>MM</span><input type="number" min="0" max="59" step="1" inputmode="numeric" data-duration-part="minutes" value="${parts.minutes}" aria-label="Target minutes"></label><span>:</span><label><span>SS</span><input type="number" min="0" max="59" step="1" inputmode="numeric" data-duration-part="seconds" value="${parts.seconds}" aria-label="Target seconds"></label></div><small>Time that earns the full score.</small></fieldset>`;
}
function advancedKey(path,value,label="Advanced identifier"){
  return `<details class="advanced-settings"><summary>${h(label)}</summary><label>Internal key<input data-path="${path}" value="${h(value)}" autocomplete="off"><small>Used by the system and exports. Avoid changing it after evaluations begin.</small></label></details>`;
}
function bindInputs(){
  $$('[data-path]',host).forEach(input=>{
    const event=input.type==="text"||input.tagName==="TEXTAREA"?"input":"change";
    input.addEventListener(event,()=>{
      let value=input.type==="checkbox"?input.checked:input.value;
      const oldValue=getPath(input.dataset.path);
      setPath(input.dataset.path,value);
      const activityKeyMatch=input.dataset.path.match(/^activities\.(\d+)\.key$/);
      if(activityKeyMatch&&oldValue!==value){
        state.draft.activities.forEach(item=>{if(item.assignment.predecessor===oldValue)item.assignment.predecessor=value;if(item.assignment.reuseAssignmentsFrom===oldValue)item.assignment.reuseAssignmentsFrom=value;});
        state.draft.dimensions.forEach(item=>{if(item.activityKey===oldValue)item.activityKey=value;});
      }
      const dimensionKeyMatch=input.dataset.path.match(/^dimensions\.(\d+)\.key$/);
      if(dimensionKeyMatch&&oldValue!==value){
        state.draft.activities.forEach(item=>item.criteria.forEach(criterion=>{if(criterion.dimensionKey===oldValue)criterion.dimensionKey=value;}));
        state.draft.scoring.components.forEach(item=>{if(item.source==="dimension"&&item.key===oldValue)item.key=value;});
      }
      if(input.dataset.path.match(/^activities\.\d+\.scoring$/)){
        const activity=state.draft.activities[Number(input.dataset.path.split(".")[1])];
        activity.criteria.forEach(item=>{item.inputType=value==="weighted_rating"?"rating":"number";item.target=value==="weighted_rating"?null:(item.target||"1");});
      }
      if(input.dataset.path.match(/^dimensions\.\d+\.source$/) && value==="activity"){
        const dimension=state.draft.dimensions[Number(input.dataset.path.split(".")[1])];
        dimension.activityKey ||= state.draft.activities[0]?.key||"";
      }
      if(input.dataset.path.match(/^scoring\.components\.\d+\.source$/)){
        const component=state.draft.scoring.components[Number(input.dataset.path.split(".")[2])];
        component.key=value==="general"?"general":(state.draft.dimensions[0]?.key||"");
      }
      const priorityMatch=input.dataset.path.match(/^assessors\.categories\.(\d+)\.(primaryPriority|secondaryPriority)$/);
      if(priorityMatch){
        const changedIndex=Number(priorityMatch[1]),field=priorityMatch[2];
        const other=state.draft.assessors.categories.find((item,index)=>index!==changedIndex&&String(item[field])===String(value));
        if(other)other[field]=oldValue;
      }
      if(input.dataset.rerender) render();
    });
  });
}

async function initialize(){
  try{
    const session=await api("/api/auth/session");
    if(!session.isOwner) throw new Error("Owner access is required.");
    state.csrf=session.csrfToken; await loadConfiguration(); showApp();
  }catch{ await showLogin(); }
}
async function showLogin(){
  $("#configLogin").classList.remove("hidden"); $("#configApp").classList.add("hidden");
  try{ state.accounts=await api("/api/auth/usernames"); wireAccountPicker($("#configUsername"),$("#configUsernames"),state.accounts); }catch{state.accounts=[];}
}
function showApp(){ $("#configLogin").classList.add("hidden"); $("#configApp").classList.remove("hidden"); render(); }
$("#configLoginForm").onsubmit=async event=>{ event.preventDefault(); const data=new FormData(event.currentTarget); try{ const account=selectedAccount(state.accounts,data.get("username")); if(!account) throw new Error("Select a username from the list."); const result=await api("/api/auth/login",{method:"POST",body:{username:account.username,password:data.get("password")}}); if(!result.isOwner) throw new Error("Owner access is required."); state.csrf=result.csrfToken; await loadConfiguration(); showApp(); }catch(error){$("#configLoginError").textContent=error.message;} };
async function loadConfiguration(){ state.payload=await api("/api/configurator"); state.draft=clone(state.payload.draft); state.dirty=false; updateChrome(); }
function updateChrome(){
  $("#configSystemName").textContent=state.draft.name; $("#configMark").textContent=state.draft.branding.shortMark||"AS";
  const root=document.documentElement,primary=state.draft.branding.primaryColor||"#4f46e5",dark=state.draft.branding.darkColor||"#172033";
  root.style.setProperty("--red",primary);root.style.setProperty("--red-dark",darken(primary));root.style.setProperty("--red-soft",`${primary}12`);root.style.setProperty("--ink",dark);root.style.setProperty("--config-blue",primary);
  $("#configMark").style.background=primary; $("#configVersion").textContent=`Published v${state.payload.system.publishedVersion}`; markSaved();
  $$(".workspace-admin-link").forEach(link=>link.href=`/${encodeURIComponent(state.payload.system.slug)}/admin`);
}

$("#configNav").onclick=event=>{ const button=event.target.closest("button[data-section]"); if(!button)return; state.section=button.dataset.section; render(); };
$("#configSave").onclick=saveDraft;
$("#configPublish").onclick=()=>{state.section="review";render();};
window.addEventListener("beforeunload",event=>{if(state.dirty){event.preventDefault();event.returnValue="";}});

async function saveDraft(){
  try{ const result=await api("/api/configurator/draft",mutation("PUT",{definition:state.draft,base_version:state.payload.system.version})); state.payload=result; state.draft=clone(result.draft); updateChrome(); toast("Configuration draft saved."); render(); }
  catch(error){ $(".config-save-state").className="config-save-state error"; $("#configStateText").textContent="Save failed"; toast(error.message,"error"); }
}
async function loadPreset(key){
  if(state.dirty&&!confirm("Replace the unsaved draft with this preset?"))return;
  if(!confirm("Load this preset into the draft? Published settings and saved assessment data will not change."))return;
  try{ const result=await api(`/api/configurator/preset/${key}`,mutation("POST",{definition:state.draft,base_version:state.payload.system.version})); state.payload=result;state.draft=clone(result.draft);state.activityIndex=0;updateChrome();state.section="basics";render();toast("Preset loaded into the draft."); }catch(error){toast(error.message,"error");}
}

function render(){
  $$("#configNav button").forEach(button=>button.classList.toggle("active",button.dataset.section===state.section));
  if(state.section==="start") renderStart();
  else if(state.section==="basics") renderBasics();
  else if(state.section==="people") renderPeople();
  else if(state.section==="activities") renderActivities();
  else if(state.section==="scoring") renderScoring();
  else if(state.section==="features") renderFeatures();
  else renderReview();
  bindInputs();
}

function renderStart(){
  host.innerHTML=heading("Configure assessment system","Workspace overview","Customize this workspace directly. It starts neutral and contains no organization-specific preset.")+`<div class="config-grid">
    <article class="config-card full"><div class="config-card-header"><div><p class="eyebrow">Workspace address</p><h2>/${h(state.payload.system.slug)}</h2><p class="muted">All admin, assessor, management, and attendance links for this workspace use this address.</p></div><button class="button ghost" data-action="copy-workspace-link">Copy link</button></div></article>
    <article class="config-card full"><div class="config-card-header"><div><h2>Current draft</h2><p class="muted">Nothing changes for operators until the owner publishes.</p></div><span class="status-pill ready">Draft</span></div><div class="review-list"><div class="review-stat"><strong>${state.draft.activities.filter(x=>x.enabled).length}</strong><small>${h(state.draft.terminology.stagePlural)}</small></div><div class="review-stat"><strong>${state.draft.dimensions.length}</strong><small>Calculated dimensions</small></div><div class="review-stat"><strong>${state.draft.assessors.categories.length}</strong><small>${h(state.draft.terminology.assessor)} categories</small></div><div class="review-stat"><strong>/${h(state.draft.scoring.officialMaximum)}</strong><small>Official score</small></div></div></article>
  </div>`;
  $('[data-action="copy-workspace-link"]',host).onclick=async()=>{await navigator.clipboard.writeText(`${location.origin}/${state.payload.system.slug}`);toast("Workspace link copied.");};
}

function renderBasics(){ const d=state.draft;
  host.innerHTML=heading("Identity","Name, theme & words","Change what the system is called and the words shown throughout the existing pages.")+`<div class="config-grid">
    <section class="config-card full"><div class="config-card-header"><div><h2>System identity</h2><p class="muted">Used on login, home, headers, and exports.</p></div></div><div class="config-fields"><label>System name<input data-path="name" value="${h(d.name)}"></label><label>Organization<input data-path="branding.organizationName" value="${h(d.branding.organizationName)}"></label><label class="wide">Description<textarea data-path="description" rows="3">${h(d.description)}</textarea></label><label>Short logo text<input data-path="branding.shortMark" maxlength="6" value="${h(d.branding.shortMark)}"></label><label>Logo image URL (optional)<input data-path="branding.logoUrl" value="${h(d.branding.logoUrl)}"></label><label>Primary color<input data-path="branding.primaryColor" type="color" value="${h(d.branding.primaryColor)}"></label><label>Dark navigation color<input data-path="branding.darkColor" type="color" value="${h(d.branding.darkColor)}"></label></div></section>
    <section class="config-card full"><div class="config-card-header"><div><h2>Terminology</h2><p class="muted">The application structure stays familiar while these displayed words change.</p></div></div><div class="config-fields">${[["system","System"],["session","Session"],["sessionPlural","Sessions"],["participant","Participant"],["participantPlural","Participants"],["assessor","Assessor"],["assessorPlural","Assessors"],["group","Group"],["groupPlural","Groups"],["stage","Activity"],["stagePlural","Activities"]].map(([key,label])=>`<label>${label}<input data-path="terminology.${key}" value="${h(d.terminology[key])}"></label>`).join("")}</div></section>
  </div>`;
}

function toggle(path,label,description){ return `<label class="config-toggle"><input type="checkbox" data-path="${path}" ${getPath(path)?"checked":""}><span><strong>${h(label)}</strong><small>${h(description)}</small></span></label>`; }
function renderPeople(){ const d=state.draft;
  host.innerHTML=heading("People & attendance","Choose who takes part","Select the information your team records, then describe any assessor categories your assignment rules should recognize.")+`<div class="config-grid">
    <section class="config-card"><h2>${h(d.terminology.participant)} records</h2><div class="toggle-list">${toggle("participants.phoneEnabled","Phone number","Show and import phone numbers.")}${toggle("participants.dateOfBirthEnabled","Date of birth","Show and import dates of birth.")}${toggle("participants.photoEnabled","Photos","Allow protected participant photos.")}${toggle("participants.arrivalTimeEnabled","Arrival time","Record presence and arrival time together.")}${toggle("participants.attendanceCommentEnabled","Attendance comment","Record tardiness or attendance details.")}</div></section>
    <section class="config-card"><h2>Linked participant list</h2><div class="toggle-list">${toggle("participants.linkedDirectoryEnabled","Use linked directory","Search a central participant list when adding attendance.")}</div><div class="config-fields" style="margin-top:14px"><label class="wide">Google Sheet URL<input data-path="participants.directorySheetUrl" value="${h(d.participants.directorySheetUrl)}"></label><label class="wide">Sheet/tab name<input data-path="participants.directorySheetName" value="${h(d.participants.directorySheetName||"Participants")}"><small>The tab containing your participant directory.</small></label></div></section>
    <section class="config-card"><div class="config-card-header"><div><h2>Linked ${h(d.terminology.assessor)} list</h2></div><button type="button" class="button ghost small" data-action="sync-assessors">Sync now</button></div><div class="toggle-list">${toggle("assessors.linkedDirectoryEnabled","Use master assessor directory","Keep reusable assessor usernames, categories, full names, and phone numbers.")}${toggle("assessors.attendanceEnabled",`${d.terminology.assessor} attendance`,`Show assessor availability for each ${d.terminology.session}.`)}</div><div class="config-fields" style="margin-top:14px"><label class="wide">Google Sheet URL (optional)<input data-path="assessors.directorySheetUrl" value="${h(d.assessors.directorySheetUrl||"")}"></label><label class="wide">Sheet/tab name<input data-path="assessors.directorySheetName" value="${h(d.assessors.directorySheetName||"Assessors")}"><small>The tab containing usernames, names, contact details, and categories.</small></label></div><p class="config-inline-help">Excel/CSV imports remain available from attendance. A published Google Sheet can also be synchronized from this page.</p></section>
    <section class="config-card full"><div class="config-card-header"><div><h2>${h(d.terminology.assessor)} categories</h2><p class="muted">Optional labels such as Senior, Junior, Technical, or External. They guide automatic assignment; they do not grant page access.</p></div><button class="button ghost small" data-action="add-category">+ Add category</button></div><div class="guidance-callout"><strong>How assignment preference works</strong><span>First, the system tries to give every ${h(d.terminology.participant.toLowerCase())} one ${h(d.terminology.assessor.toLowerCase())}. The first preference controls those assignments. If an activity allows additional ${h(d.terminology.assessorPlural.toLowerCase())}, the additional preference is used only after everyone has one.</span></div><div class="repeat-list category-list">${d.assessors.categories.map((item,index)=>`<div class="config-row category"><label>Category name<input data-path="assessors.categories.${index}.name" value="${h(item.name)}"></label><label>Preference for the first ${h(d.terminology.assessor.toLowerCase())}<select data-path="assessors.categories.${index}.primaryPriority" data-rerender="1">${priorityOptions(item.primaryPriority,d.assessors.categories.length)}</select><small>First choice is tried before second choice.</small></label><label>Preference for additional ${h(d.terminology.assessorPlural.toLowerCase())}<select data-path="assessors.categories.${index}.secondaryPriority" data-rerender="1">${priorityOptions(item.secondaryPriority,d.assessors.categories.length)}</select><small>Used only when an activity allows more than one.</small></label><button class="button danger small" data-action="remove-category" data-index="${index}" ${d.assessors.categories.length===1?"disabled":""}>Remove</button>${advancedKey(`assessors.categories.${index}.key`,item.key)}</div>`).join("")}</div></section>
  </div>`;
  $('[data-action="add-category"]',host).onclick=()=>{d.assessors.categories.push({key:uniqueKey("category",d.assessors.categories),name:"New category",primaryPriority:d.assessors.categories.length,secondaryPriority:d.assessors.categories.length,color:"#64748b"});markDirty();render();};
  $$('[data-action="remove-category"]',host).forEach(button=>button.onclick=()=>{d.assessors.categories.splice(Number(button.dataset.index),1);normalizeCategoryPriorities(d.assessors);markDirty();render();});
  $('[data-action="sync-assessors"]',host).onclick=async()=>{try{const result=await api("/api/configurator/sync-assessors",mutation("POST",{definition:d,base_version:state.payload.system.version}));toast(`${result.imported} assessor records synchronized.`);}catch(error){toast(error.message,"error");}};
}

function criterionScope(definition,activity,criterion){
  if(criterion.dimensionKey){
    const dimension=definition.dimensions.find(item=>item.key===criterion.dimensionKey);
    const criteria=definition.activities.filter(item=>item.enabled||item.key===activity.key).flatMap(item=>item.criteria).filter(item=>item.dimensionKey===criterion.dimensionKey);
    return {key:`dimension:${criterion.dimensionKey}`,name:dimension?.name||criterion.dimensionKey,label:`Weight within ${dimension?.name||"dimension"}`,total:criteria.reduce((sum,item)=>sum+Number(item.weight||0),0)};
  }
  const criteria=activity.criteria.filter(item=>!item.dimensionKey);
  const activityDimension=definition.dimensions.find(item=>item.source==="activity"&&item.activityKey===activity.key);
  return {key:`activity:${activity.key}`,name:activityDimension?.name||activity.name,label:activityDimension?`Weight within ${activityDimension.name}`:"Weight within this activity",total:criteria.reduce((sum,item)=>sum+Number(item.weight||0),0)};
}
function criteriaForScope(definition,activity,scopeKey){
  const separator=scopeKey.indexOf(":"),type=scopeKey.slice(0,separator),key=scopeKey.slice(separator+1);
  if(type==="dimension")return definition.activities.filter(item=>item.enabled||item.key===activity.key).flatMap(item=>item.criteria).filter(item=>item.dimensionKey===key);
  return activity.criteria.filter(item=>!item.dimensionKey);
}
function updateCriterionWeightTotals(definition,activity){
  const totals=new Map();
  activity.criteria.forEach(item=>{const scope=criterionScope(definition,activity,item);totals.set(scope.key,scope.total);});
  $$('[data-weight-summary]',host).forEach(summary=>{const total=totals.get(summary.dataset.weightSummary)||0,complete=Math.abs(total-1)<=.0001;summary.classList.toggle("complete",complete);summary.classList.toggle("needs-review",!complete);$('[data-weight-total]',summary).textContent=`${percentValue(total)}%`;$('[data-weight-state]',summary).textContent=complete?"Totals 100%":"Review total";});
  $$('[data-scope-total]',host).forEach(label=>{label.textContent=`Current total: ${percentValue(totals.get(label.dataset.scopeTotal)||0)}%`;});
}

function renderActivities(){
  const d=state.draft;
  state.activityIndex=Math.max(0,Math.min(state.activityIndex,d.activities.length-1));
  const a=d.activities[state.activityIndex];
  const activityOptions=d.activities.map(item=>[item.key,item.name]);
  const dimensionOptions=d.dimensions.map(item=>[item.key,item.name]);
  const scopes=[...new Map(a.criteria.map(item=>{const scope=criterionScope(d,a,item);return[scope.key,scope];})).values()];
  const weightOverview=scopes.length?`<div class="weight-overview" aria-label="Criterion weight totals">${scopes.map(scope=>`<div class="weight-summary ${Math.abs(scope.total-1)>.0001?"needs-review":"complete"}" data-weight-summary="${h(scope.key)}"><span>${h(scope.name)}</span><strong data-weight-total>${percentValue(scope.total)}%</strong><small data-weight-state>${Math.abs(scope.total-1)>.0001?"Review total":"Totals 100%"}</small><button type="button" class="button ghost small" data-action="balance-criterion-weights" data-scope="${h(scope.key)}" title="${scope.key.startsWith("dimension:")?"Give every criterion in this dimension, across all activities, an equal percentage.":"Give every activity-only criterion an equal percentage."}">${scope.key.startsWith("dimension:")?"Balance across activities":"Balance this activity"}</button></div>`).join("")}</div>`:"";
  const criteria=a.criteria.map((item,index)=>{
    const scope=criterionScope(d,a,item);
    const target=a.scoring==="weighted_rating"?"":item.inputType==="duration"
      ?durationTarget(index,item.target)
      :`<label>Full-score target<input type="number" min="0.0001" step="0.1" data-path="activities.${state.activityIndex}.criteria.${index}.target" value="${item.target??""}"><small>The result that earns 5/5.</small></label>`;
    const ratingScale=a.scoring==="weighted_rating"?`<label>Lowest allowed rating<input type="number" step="any" data-path="activities.${state.activityIndex}.criteria.${index}.minimum" value="${h(item.minimum)}"><small>The bottom of the assessor's scale.</small></label><label>Highest allowed rating<input type="number" step="any" data-path="activities.${state.activityIndex}.criteria.${index}.maximum" value="${h(item.maximum)}"><small>The top of the assessor's scale.</small></label><label>Rating step<input type="number" min="0.0001" step="any" data-path="activities.${state.activityIndex}.criteria.${index}.step" value="${h(item.step)}"><small>Use 1 for whole ratings or 0.5 for half-points.</small></label>`:"";
    return `<article class="config-row criteria"><div class="criterion-editor-heading"><strong>${h(item.name||`Criterion ${index+1}`)}</strong><button class="button danger small" data-action="remove-criterion" data-index="${index}" ${a.criteria.length===1?"disabled":""} aria-label="Remove ${h(item.name||"criterion")}">&times;</button></div><label>Criterion name<input data-path="activities.${state.activityIndex}.criteria.${index}.name" value="${h(item.name)}"></label><label>Measures which dimension?<select data-path="activities.${state.activityIndex}.criteria.${index}.dimensionKey" data-rerender="1"><option value="">Activity score only</option>${dimensionOptions.map(([key,name])=>option(key,name,item.dimensionKey)).join("")}</select><small>This decides which dimension receives the result.</small></label><label>What does the assessor enter?<select data-path="activities.${state.activityIndex}.criteria.${index}.inputType" data-rerender="1">${a.scoring==="weighted_rating"?option("rating","A rating",item.inputType):[option("integer","A whole number",item.inputType),option("number","A number",item.inputType),option("duration","A duration",item.inputType)].join("")}</select></label><label>${h(scope.label)} (%)<input type="number" min="0.01" max="100" step="0.01" data-criterion-weight="${index}" data-weight-scope="${h(scope.key)}" value="${percentValue(item.weight)}"><small data-scope-total="${h(scope.key)}">Current total: ${percentValue(scope.total)}%</small></label>${target}${a.scoring==="weighted_rating"?"":`<label>Which result is better?<select data-path="activities.${state.activityIndex}.criteria.${index}.direction">${option("higher","Higher result",item.direction)}${option("lower","Lower result",item.direction)}</select><small>The target or any better result earns the full 5/5.</small></label>`}${ratingScale}<label>Unit (optional)<input data-path="activities.${state.activityIndex}.criteria.${index}.unit" value="${h(item.unit)}" placeholder="e.g. repetitions"></label><label class="criterion-explanation">Guidance shown to assessors<textarea rows="2" data-path="activities.${state.activityIndex}.criteria.${index}.explanation">${h(item.explanation)}</textarea></label>${advancedKey(`activities.${state.activityIndex}.criteria.${index}.key`,item.key,"Advanced criterion identifier")}</article>`;
  }).join("");
  host.innerHTML=heading("Activities & forms",d.terminology.stagePlural,"Set up what happens in each activity and what assessors complete.",`<button class="button primary" data-action="add-activity">+ Add ${h(d.terminology.stage)}</button>`)+`<div class="activity-layout"><aside class="activity-list">${d.activities.map((item,index)=>`<button class="${index===state.activityIndex?"active":""}" data-activity-index="${index}"><span><strong>${h(item.name)}</strong><small>${h(item.assignment.mode.replaceAll("_"," "))}</small></span><span aria-hidden="true">&rsaquo;</span></button>`).join("")}</aside><section class="config-card full activity-editor">
    <div class="config-card-header"><div><p class="eyebrow">${h(d.terminology.stage)} ${state.activityIndex+1}</p><h2>${h(a.name)}</h2></div><div class="inline-actions"><button class="button ghost small icon-button" data-action="move-up" ${state.activityIndex===0?"disabled":""} aria-label="Move activity up">&uarr;</button><button class="button ghost small icon-button" data-action="move-down" ${state.activityIndex===d.activities.length-1?"disabled":""} aria-label="Move activity down">&darr;</button><button class="button danger small" data-action="remove-activity" ${d.activities.length===1?"disabled":""}>Remove</button></div></div>
    <div class="config-fields activity-basics"><label>Activity name<input data-path="activities.${state.activityIndex}.name" value="${h(a.name)}"></label><label>How is it scored?<select data-path="activities.${state.activityIndex}.scoring" data-rerender="1">${option("weighted_rating","Assessors give ratings",a.scoring)}${option("target_average","Assessors enter measured results",a.scoring)}</select><small>${a.scoring==="weighted_rating"?"Use for interviews, observations, and scorecards.":"Use for counts, measurements, and timed tests."}</small></label><label>How are assessors assigned?<select data-path="activities.${state.activityIndex}.assignment.mode">${option("automatic_global","Automatically across everyone",a.assignment.mode)}${option("automatic_groups","Automatically within groups or rooms",a.assignment.mode)}${option("manual","Manually",a.assignment.mode)}</select></label><label>Maximum assessors per ${h(d.terminology.participant.toLowerCase())}<input type="number" min="1" max="100" step="1" inputmode="numeric" data-path="activities.${state.activityIndex}.assignment.maximumAssessors" value="${h(a.assignment.maximumAssessors)}"><small>Set this separately for each activity. Automatic assignment will not exceed it; manual edits may.</small></label><label class="config-toggle"><input type="checkbox" data-path="activities.${state.activityIndex}.enabled" ${a.enabled?"checked":""}><span><strong>Use this activity</strong><small>Show it in sessions and assessor forms.</small></span></label>${advancedKey(`activities.${state.activityIndex}.key`,a.key,"Advanced activity identifier")}</div>
    <details class="advanced-panel"><summary>Advanced scheduling and assignment rules</summary><div class="config-fields"><label>Must follow<select data-path="activities.${state.activityIndex}.assignment.predecessor"><option value="">No required previous activity</option>${activityOptions.filter(([key])=>key!==a.key).map(([key,name])=>option(key,name,a.assignment.predecessor)).join("")}</select><small>This activity cannot open before the selected one.</small></label><label>Use the same assignments as<select data-path="activities.${state.activityIndex}.assignment.reuseAssignmentsFrom"><option value="">Create separate assignments</option>${activityOptions.filter(([key])=>key!==a.key).map(([key,name])=>option(key,name,a.assignment.reuseAssignmentsFrom)).join("")}</select><small>Every assessor keeps the same participant assignments.</small></label><label>Open-together group (optional)<input data-path="activities.${state.activityIndex}.assignment.parallelGroup" value="${h(a.assignment.parallelGroup)}" placeholder="e.g. practical_block"><small>Activities with the same value may be open together.</small></label></div></details>
    <div class="toggle-list activity-toggles">${toggle(`activities.${state.activityIndex}.assignment.avoidRepeatPairs`,"Avoid repeated assessor–participant pairs","Prefer a different pairing from earlier activities when possible.")}${toggle(`activities.${state.activityIndex}.assignment.mandatoryPlacements`,"Allow required group placements","Let admins require specific assessors in a group or room.")}${toggle(`activities.${state.activityIndex}.evaluatorShowsDescriptions`,"Show criterion guidance","Display the guidance written below on the assessor form.")}${toggle(`activities.${state.activityIndex}.evaluatorShowsDimensions`,"Show dimension names","Tell assessors which dimension each criterion measures.")}${toggle(`activities.${state.activityIndex}.commentsEnabled`,"Allow comments","Show an optional comment field on this evaluation.")}</div>
    <div class="config-divider"></div><div class="config-card-header"><div><h3>Evaluation criteria</h3><p class="muted">Choose what assessors enter and how each answer contributes to the results.</p></div><button class="button ghost small" data-action="add-criterion">+ Add criterion</button></div><div class="guidance-callout"><strong>What the percentage means</strong><span>When a criterion measures a dimension, its percentage is its share of that dimension across all activities. All criteria assigned to the same dimension must total 100%. If you select “Activity score only,” the percentage is its share of this activity instead.</span></div>${weightOverview}<div class="repeat-list criteria-list">${criteria}</div>
  </section></div>`;
  $$('[data-activity-index]',host).forEach(button=>button.onclick=()=>{state.activityIndex=Number(button.dataset.activityIndex);render();});
  $('[data-action="add-activity"]',host).onclick=()=>{const n=d.activities.length+1;d.activities.push({key:uniqueKey("activity",d.activities),name:`Activity ${n}`,enabled:true,scoring:"weighted_rating",criteria:[{key:"performance",dimensionKey:d.dimensions[0]?.key||"",dimensionName:d.dimensions[0]?.name||"",name:"Performance",explanation:"",weight:"1",inputType:"rating",minimum:"0",maximum:"5",step:"0.1",target:null,direction:"higher",unit:""}],assignment:{mode:"automatic_global",maximumAssessors:1,avoidRepeatPairs:true,predecessor:"",reuseAssignmentsFrom:"",parallelGroup:"",mandatoryPlacements:false},evaluatorShowsDescriptions:true,evaluatorShowsDimensions:true,commentsEnabled:true});state.activityIndex=d.activities.length-1;markDirty();render();};
  $('[data-action="remove-activity"]',host).onclick=()=>{if(confirm(`Remove ${a.name} from the draft?`)){d.activities.splice(state.activityIndex,1);state.activityIndex=Math.max(0,state.activityIndex-1);markDirty();render();}};
  $('[data-action="move-up"]',host).onclick=()=>{[d.activities[state.activityIndex-1],d.activities[state.activityIndex]]=[d.activities[state.activityIndex],d.activities[state.activityIndex-1]];state.activityIndex--;markDirty();render();};
  $('[data-action="move-down"]',host).onclick=()=>{[d.activities[state.activityIndex+1],d.activities[state.activityIndex]]=[d.activities[state.activityIndex],d.activities[state.activityIndex+1]];state.activityIndex++;markDirty();render();};
  $('[data-action="add-criterion"]',host).onclick=()=>{const n=a.criteria.length+1;a.criteria.push({key:uniqueKey("criterion",a.criteria),dimensionKey:d.dimensions[0]?.key||"",dimensionName:d.dimensions[0]?.name||"",name:`Criterion ${n}`,explanation:"",weight:"1",inputType:a.scoring==="weighted_rating"?"rating":"number",minimum:"0",maximum:"5",step:"0.1",target:a.scoring==="weighted_rating"?null:"1",direction:"higher",unit:""});markDirty();render();};
  $$('[data-action="remove-criterion"]',host).forEach(button=>button.onclick=()=>{a.criteria.splice(Number(button.dataset.index),1);markDirty();render();});
  $$('[data-criterion-weight]',host).forEach(input=>input.oninput=()=>{a.criteria[Number(input.dataset.criterionWeight)].weight=String(Number(input.value||0)/100);markDirty();updateCriterionWeightTotals(d,a);});
  $$('[data-action="balance-criterion-weights"]',host).forEach(button=>button.onclick=()=>{balanceWeights(criteriaForScope(d,a,button.dataset.scope));markDirty();render();});
  $$('[data-duration-target]',host).forEach(fieldset=>fieldset.oninput=()=>{const criterion=a.criteria[Number(fieldset.dataset.durationTarget)];const hours=Math.max(0,Math.min(99,Math.round(Number($('[data-duration-part="hours"]',fieldset).value)||0)));const minutes=Math.max(0,Math.min(59,Math.round(Number($('[data-duration-part="minutes"]',fieldset).value)||0)));const seconds=Math.max(0,Math.min(59,Math.round(Number($('[data-duration-part="seconds"]',fieldset).value)||0)));criterion.target=String(hours*3600+minutes*60+seconds);markDirty();});
}

function renderScoring(){const d=state.draft;const activityOptions=d.activities.map(item=>[item.key,item.name]);const sourceOptions=d.dimensions.map(item=>[item.key,item.name]);const total=d.scoring.components.reduce((sum,item)=>sum+Number(item.weight||0),0)*100;
  const rankingChoices=[
    ["competition","Shared ranks, with gaps","Tied participants share a rank. The following position is skipped: 1, 2, 2, 4."],
    ["dense","Shared ranks, without gaps","Tied participants share a rank. The next rank continues normally: 1, 2, 2, 3."],
    ["ordinal","A unique position for everyone","Every participant receives a different position: 1, 2, 3, 4, even when scores are tied."],
  ];
  host.innerHTML=heading("Scoring & results","Build the final result","Connect criteria to dimensions, add any organization-wide assessment factors, and choose how results are displayed.")+`<div class="config-grid">
    <section class="config-card full"><div class="config-card-header"><div><h2>Calculated dimensions</h2><p class="muted">A dimension can combine criteria from several activities, or use the final score from one activity.</p></div><button class="button ghost small" data-action="add-dimension">+ Add dimension</button></div><div class="repeat-list">${d.dimensions.map((item,index)=>`<div class="config-row dimension"><label>Dimension name<input data-path="dimensions.${index}.name" value="${h(item.name)}"></label><label>How is it calculated?<select data-path="dimensions.${index}.source" data-rerender="1">${option("criteria","Combine criteria assigned to it",item.source)}${option("activity","Use one activity score",item.source)}</select></label><label>${item.source==="activity"?"Activity":"Included criteria"}${item.source==="activity"?`<select data-path="dimensions.${index}.activityKey">${activityOptions.map(([key,name])=>option(key,name,item.activityKey)).join("")}</select>`:`<input value="Selected inside each activity" disabled>`}</label><button class="button danger small" data-action="remove-dimension" data-index="${index}" ${d.dimensions.length===1?"disabled":""}>Remove</button>${advancedKey(`dimensions.${index}.key`,item.key,"Advanced dimension identifier")}</div>`).join("")}</div></section>
    <section class="config-card full"><div class="config-card-header"><div><h2>General assessment</h2><p class="muted">Optional factors scored outside individual activities, such as motivation, portfolio quality, or professionalism. Add only what your process needs.</p></div><button class="button ghost small" data-action="add-general-factor">+ Add factor</button></div>${d.generalFactors.length?`<div class="guidance-callout"><strong>How this score is calculated</strong><span>Factors are normalized to their own maximum and combined into one general-assessment average. Add that average below if it should affect the official score.</span></div><div class="repeat-list general-factor-list">${d.generalFactors.map((item,index)=>`<div class="config-row general-factor"><label>Factor name<input data-path="generalFactors.${index}.name" value="${h(item.name)}" placeholder="e.g. Motivation"></label><label>Maximum score<input type="number" min="0.1" max="100" step="0.1" data-path="generalFactors.${index}.maximum" value="${h(item.maximum)}"></label><label>Allowed step<input type="number" min="0.01" max="100" step="0.01" data-path="generalFactors.${index}.step" value="${h(item.step)}"><small>For example, 0.5 allows 3, 3.5, 4.</small></label><button class="button danger small" data-action="remove-general-factor" data-index="${index}">Remove</button>${advancedKey(`generalFactors.${index}.storageKey`,item.storageKey,"Advanced factor identifier")}</div>`).join("")}</div>`:`<div class="empty-config"><strong>No general assessment</strong><p>Your final result currently comes only from activity dimensions. Add a factor if your process needs a separate overall judgement.</p></div>`}</section>
    <section class="config-card full"><div class="config-card-header"><div><h2>Score display and ranking</h2><p class="muted">Choose the scale people see and what happens when two participants receive the same score.</p></div></div><div class="score-display-grid"><label>Official score is out of<input type="number" min="1" step="1" data-path="scoring.officialMaximum" value="${h(d.scoring.officialMaximum)}"><small>Examples: 5, 20, or 100.</small></label><fieldset class="ranking-choices"><legend>When scores are tied</legend>${rankingChoices.map(([value,title,description])=>`<label class="choice-card ${d.scoring.ranking===value?"selected":""}"><input type="radio" name="rankingMode" value="${value}" data-path="scoring.ranking" data-rerender="1" ${d.scoring.ranking===value?"checked":""}><span><strong>${h(title)}</strong><small>${h(description)}</small></span></label>`).join("")}</fieldset></div><div class="config-fields score-behavior"><label>When several assessors are assigned<select data-path="scoring.assessorAggregation">${option("available_average","Average evaluations that were submitted",d.scoring.assessorAggregation)}${option("missing_as_zero","Count each missing evaluation as zero",d.scoring.assessorAggregation)}</select><small>Controls the activity score while submissions are missing.</small></label><label>When a score component is missing<select data-path="scoring.missingComponents">${option("zero","Count the missing component as zero",d.scoring.missingComponents)}${option("exclude","Exclude it and reweight completed components",d.scoring.missingComponents)}</select><small>Controls the participant&rsquo;s official score.</small></label></div></section>
    <section class="config-card full"><div class="config-card-header"><div><h2>Overall score components</h2><p class="muted">Weights must total exactly 100%.</p></div><div class="inline-actions"><span class="weight-total ${Math.abs(total-100)>.001?"invalid":""}">${total.toFixed(2)}%</span><button class="button ghost small" data-action="equal-weights">Equal weights</button><button class="button ghost small" data-action="add-component">+ Add</button></div></div><div class="repeat-list">${d.scoring.components.map((item,index)=>`<div class="config-row component"><label>Source<select data-path="scoring.components.${index}.source" data-rerender="1">${option("dimension","Dimension",item.source)}${option("general","General average",item.source)}</select></label><label>Component${item.source==="general"?`<input value="General assessment average" disabled>`:`<select data-path="scoring.components.${index}.key">${sourceOptions.map(([key,name])=>option(key,name,item.key)).join("")}</select>`}</label><label>Weight %<input type="number" min="0.01" max="100" step="0.01" data-component-weight="${index}" value="${(Number(item.weight)*100).toFixed(6).replace(/0+$/,'').replace(/\.$/,'')}"></label><button class="button danger small" data-action="remove-component" data-index="${index}" ${d.scoring.components.length===1?"disabled":""}>Remove</button></div>`).join("")}</div></section>
    <section class="config-card full"><div class="config-card-header"><div><h2>Performance/color bands</h2><p class="muted">The first band must start at zero.</p></div><button class="button ghost small" data-action="add-band">+ Add band</button></div><div class="repeat-list">${d.scoring.bands.map((item,index)=>`<div class="config-row band"><label>Name<input data-path="scoring.bands.${index}.name" value="${h(item.name)}"></label><label>Minimum score<input type="number" min="0" step="0.01" data-path="scoring.bands.${index}.minimum" value="${h(item.minimum)}"></label><label>Color<input type="color" data-path="scoring.bands.${index}.color" value="${h(item.color)}"></label><button class="button danger small" data-action="remove-band" data-index="${index}" ${d.scoring.bands.length===1?"disabled":""}>Remove</button></div>`).join("")}</div></section>
  </div>`;
  $('[data-action="add-dimension"]',host).onclick=()=>{const n=d.dimensions.length+1;d.dimensions.push({key:uniqueKey("dimension",d.dimensions),name:`Dimension ${n}`,source:"criteria",activityKey:"",displayMaximum:"5"});markDirty();render();};
  $$('[data-action="remove-dimension"]',host).forEach(button=>button.onclick=()=>{const index=Number(button.dataset.index),key=d.dimensions[index].key;if(d.scoring.components.some(x=>x.source==="dimension"&&x.key===key)||d.activities.some(a=>a.criteria.some(c=>c.dimensionKey===key))){toast("Remove this dimension from criteria and score components first.","error");return;}d.dimensions.splice(index,1);markDirty();render();});
  $('[data-action="add-general-factor"]',host).onclick=()=>{const n=d.generalFactors.length+1;d.generalFactors.push({storageKey:uniqueKey("factor",d.generalFactors,"storageKey"),name:`Factor ${n}`,maximum:"5",step:"0.1"});markDirty();render();};
  $$('[data-action="remove-general-factor"]',host).forEach(button=>button.onclick=()=>{const index=Number(button.dataset.index),factor=d.generalFactors[index];if(!confirm(`Remove ${factor.name} from the general assessment?`))return;d.generalFactors.splice(index,1);if(!d.generalFactors.length){d.scoring.components=d.scoring.components.filter(item=>item.source!=="general");if(!d.scoring.components.length&&d.dimensions.length)d.scoring.components.push({source:"dimension",key:d.dimensions[0].key,weight:"1"});}markDirty();render();});
  $$('[data-component-weight]',host).forEach(input=>input.oninput=()=>{d.scoring.components[Number(input.dataset.componentWeight)].weight=String(Number(input.value||0)/100);markDirty();});
  $('[data-action="equal-weights"]',host).onclick=()=>{balanceWeights(d.scoring.components);markDirty();render();};
  $('[data-action="add-component"]',host).onclick=()=>{d.scoring.components.push({source:"dimension",key:d.dimensions[0].key,weight:"0.1"});markDirty();render();};
  $$('[data-action="remove-component"]',host).forEach(button=>button.onclick=()=>{d.scoring.components.splice(Number(button.dataset.index),1);markDirty();render();});
  $('[data-action="add-band"]',host).onclick=()=>{const n=d.scoring.bands.length+1;d.scoring.bands.push({key:uniqueKey("band",d.scoring.bands),name:`Band ${n}`,minimum:"0",color:"#64748b"});markDirty();render();};
  $$('[data-action="remove-band"]',host).forEach(button=>button.onclick=()=>{d.scoring.bands.splice(Number(button.dataset.index),1);markDirty();render();});
}

function renderFeatures(){const d=state.draft;const featureLabels={participantAttendance:[`${d.terminology.participant} attendance`,`Presence, arrival, photos, contact details, and comments.`],assessorAttendance:[`${d.terminology.assessor} attendance`,`Availability and category shown before assignment.`],groupsAndRooms:[`${d.terminology.groupPlural} and group plans`,`Room/group distribution and capacity.`],mandatoryPlacements:[`Mandatory placements`,`Require selected assessors inside groups.`],liveDashboard:[`Live dashboard`,`Operational counts, progress, averages, and warnings.`],managementPortal:[`Management portal`,`Read-only attendance, results, and profiles.`],attendancePortal:[`Attendance portal`,`Mobile link dedicated to participant attendance.`],resultsAndRankings:[`Results and rankings`,`Activity, dimension, and overall rankings.`],participantProfiles:[`${d.terminology.participant} profiles`,`Detailed scores, charts, comments, and history.`],generalAssessment:[`General assessment`,`General factors and comments on participant profiles.`],notes:[`Private notes`,`Separate administrative notes on profiles.`],excelReports:[`Excel reports`,`View-only reports and management workbook.`],evaluationSimulator:[`Local evaluation simulator`,`Development-only workflow testing tool.`]};
  const capabilityLabels={evaluate:`${d.terminology.assessor} workspace`,admin:"Admin workspace",results:"Management results",attendance:"Attendance portal"};
  const dashboardLabels={attendanceCounts:"Attendance counts",assessorCategories:"Assessor category counts",activeStage:"Active activity",submissionProgress:"Live submission progress",warnings:"Operational warnings",stageLifecycle:"Activity lifecycle",provisionalRanking:"Provisional ranking",averages:"Dimension and activity averages"};
  host.innerHTML=heading("Pages & access","Choose what each team needs","Turn pages on or off, simplify the live dashboard, and create permission profiles for the people using this workspace.")+`<div class="config-grid"><section class="config-card full"><div class="config-card-header"><div><h2>Enabled modules</h2><p class="muted">Turn off anything your process does not use. Disabled modules disappear from navigation.</p></div></div><div class="config-fields">${Object.entries(featureLabels).map(([key,[label,desc]])=>toggle(`features.${key}`,label,desc)).join("")}</div></section><section class="config-card full"><div class="config-card-header"><div><h2>Dashboard widgets</h2><p class="muted">Choose the information administrators see first during a session.</p></div></div><div class="config-fields">${Object.entries(dashboardLabels).map(([key,label])=>toggle(`dashboard.${key}`,label,"Show this information on the live dashboard.")).join("")}</div></section><section class="config-card full"><div class="config-card-header"><div><h2>Permission profiles</h2><p class="muted">Create as many reusable access profiles as your team needs, then choose one when creating an account.</p></div><button class="button ghost small" data-action="add-access-profile">+ Add profile</button></div><div class="guidance-callout"><strong>Profiles are starting points</strong><span>The Owner always keeps full access. A profile copies its permissions to a new account once; removing or changing it later does not silently alter existing accounts. Attendance access is still selected separately for each session.</span></div><div class="repeat-list access-profile-list">${d.accessProfiles.map((item,index)=>`<article class="config-row access-profile ${item.key==="owner"?"protected":""}"><div class="profile-title"><label>Profile name<input data-path="accessProfiles.${index}.name" value="${h(item.name)}"></label>${item.key==="owner"?`<span class="status-pill ready">Protected</span>`:""}</div><label>Description<input data-path="accessProfiles.${index}.description" value="${h(item.description)}" placeholder="Who should use this profile?"></label><label class="config-toggle"><input type="checkbox" data-path="accessProfiles.${index}.enabled" ${item.enabled?"checked":""} ${item.key==="owner"?"disabled":""}><span><strong>Available for accounts</strong><small>${item.enabled?"Can be selected when adding a user.":"Hidden when adding a user."}</small></span></label><fieldset class="access-capabilities"><legend>Pages this profile can open</legend>${Object.entries(capabilityLabels).map(([capability,label])=>`<label><input type="checkbox" data-capability-profile="${index}" value="${capability}" ${(item.capabilities||[]).includes(capability)?"checked":""} ${item.key==="owner"?"disabled":""}> ${h(label)}</label>`).join("")}</fieldset><button class="button danger small" data-action="remove-access-profile" data-index="${index}" ${item.key==="owner"?"disabled":""}>Remove profile</button>${item.key==="owner"?`<details class="advanced-settings"><summary>Advanced profile identifier</summary><label>Internal key<input value="owner" disabled></label></details>`:advancedKey(`accessProfiles.${index}.key`,item.key,"Advanced profile identifier")}</article>`).join("")}</div></section></div>`;
  $$('[data-capability-profile]',host).forEach(box=>box.onchange=()=>{const profile=d.accessProfiles[Number(box.dataset.capabilityProfile)];profile.capabilities=profile.capabilities||[];if(box.checked&&!profile.capabilities.includes(box.value))profile.capabilities.push(box.value);if(!box.checked)profile.capabilities=profile.capabilities.filter(value=>value!==box.value);markDirty();});
  $('[data-action="add-access-profile"]',host).onclick=()=>{const n=d.accessProfiles.filter(item=>item.key!=="owner").length+1;d.accessProfiles.push({key:uniqueKey("profile",d.accessProfiles),name:`New profile ${n}`,description:"",enabled:true,capabilities:[]});markDirty();render();};
  $$('[data-action="remove-access-profile"]',host).forEach(button=>button.onclick=()=>{const index=Number(button.dataset.index),profile=d.accessProfiles[index];if(profile.key==="owner")return;if(!confirm(`Remove the ${profile.name} permission profile? Existing accounts keep their current permissions.`))return;d.accessProfiles.splice(index,1);markDirty();render();});
}

async function renderReview(){const d=state.draft;host.innerHTML=heading("Final check","Review & publish","Validate the complete setup before it replaces the currently published behavior.",`<button class="button ghost" data-action="validate">Validate now</button><button class="button primary" data-action="publish">Publish configuration</button>`)+`<div class="config-grid"><section class="config-card full"><div class="review-list"><div class="review-stat"><strong>${d.activities.filter(x=>x.enabled).length}</strong><small>${h(d.terminology.stagePlural)}</small></div><div class="review-stat"><strong>${d.activities.reduce((sum,x)=>sum+x.criteria.length,0)}</strong><small>Evaluation criteria</small></div><div class="review-stat"><strong>${d.dimensions.length}</strong><small>Dimensions</small></div><div class="review-stat"><strong>/${h(d.scoring.officialMaximum)}</strong><small>Official score</small></div></div></section><section class="config-card full" id="validationPanel"><h2>Validation</h2><p class="muted">Press Validate now to check names, score weights, targets, linked settings, and historical compatibility.</p></section><section class="config-card full"><h2>Publishing safety</h2><div class="${state.payload.impact.blocked?"config-warning":"config-success"}"><strong>${state.payload.impact.blocked?"Structural publishing is protected":"Safe to publish compatible edits"}</strong><p>${h(state.payload.impact.message)}</p></div><p class="config-inline-help">Only this workspace is changed. Other workspaces remain independent.</p></section><section class="config-card full"><label>Change summary<textarea id="changeSummary" rows="3" placeholder="What changed and why?"></textarea></label><div class="inline-actions" style="margin-top:14px"><button class="button primary" data-action="publish">Publish configuration</button><button class="button ghost" data-action="save-review">Save draft only</button></div></section></div>`;
  $$('[data-action="validate"]',host).forEach(button=>button.onclick=validateDraft);$$('[data-action="publish"]',host).forEach(button=>button.onclick=publishDraft);$('[data-action="save-review"]',host).onclick=saveDraft;
}
async function validateDraft(){const panel=$("#validationPanel");try{const result=await api("/api/configurator/validate",{method:"POST",body:{definition:state.draft,base_version:state.payload.system.version}});panel.innerHTML=`<h2>Validation</h2><div class="config-success"><strong>Configuration is valid.</strong><p>${h(result.impact.message)}</p></div>`;}catch(error){panel.innerHTML=`<h2>Validation</h2><div class="config-errors"><strong>Fix this before publishing</strong><p>${h(error.message)}</p></div>`;}}
async function publishDraft(){if(!confirm("Publish this configuration to the workspace?"))return;try{const result=await api("/api/configurator/publish",mutation("POST",{definition:state.draft,base_version:state.payload.system.version,change_summary:$("#changeSummary")?.value||"Configuration updated."}));state.payload=result;state.draft=clone(result.draft);updateChrome();toast("Workspace configuration published.");render();}catch(error){toast(error.message,"error");await validateDraft();}}

host.addEventListener("click",event=>{const button=event.target.closest("button");if(button?.disabled)event.preventDefault();});
initialize();
